<template>
  <AppLoader v-if="isLoadingUserShortInfo" subject="user dashboard" />
  <AppError
    v-else-if="ErrorUserShortInfo || !userShortInfo"
    :error="ErrorUserShortInfo"
    title="Failed to load user dashboard"
  />
  <section v-else class="flex flex-col gap-10">
    <PageTitle :title="`${username(userShortInfo)} - Dashboard`" />
    <div class="flex flex-col gap-6">
      <UserDashboardNavigation
        :calculated-at="data?.calculated_at"
        :user-id="userId"
        :params="params"
        :default-date="defaultDate"
      />
      <AppLoader v-if="isLoading" subject="dashboard" />
      <AppError v-else-if="error" title="Failed to load dashboard" :error="error" />
      <AppEmpty v-else-if="!data?.charts" subject="project charts" />
      <div v-else class="grid grid-cols-12 gap-4">
        <DashboardChartsCard
          :charts="data.charts"
          :params="params"
          :query-key="['canvasser.id.dashboard', userId, params]"
          :map-type="null"
        />
      </div>
    </div>
  </section>
</template>

<script setup lang="ts">
import { getUserShortInfo, getCanvasserDashboard } from '~/client';
import type { GetCanvasserDashboardData } from '~/client';

definePageMeta({
  roles: ['admin'],
  backLabel: 'dashboard',
});

const route = useRoute('users-id-dashboard');
const userId = computed(() => route.params.id);

const {
  data: userShortInfo,
  isLoading: isLoadingUserShortInfo,
  error: ErrorUserShortInfo,
} = useQuery({
  key: () => ['user.short-info', userId.value],
  query: () => getUserShortInfo({ composable: '$fetch', path: { user_id: userId.value } }),
  enabled: () => !!userId.value,
});

const canvasserName = computed(() => (userShortInfo.value ? username(userShortInfo.value) : 'Canvasser'));

useHead({
  title: `${canvasserName.value} Dashboard`,
});

const defaultDate = ref<{ startDate: string; endDate: string }>(calculateDefaultDate());

function calculateDefaultDate() {
  const startDate = dateFromNowWithDaysGap(new Date(), 29);
  const defaultStartDate = formatDateToFormat(startDate, 'yyyy-MM-dd');
  const defaultEndDate = formatDateToFormat(new Date(), 'yyyy-MM-dd');
  return { startDate: defaultStartDate, endDate: defaultEndDate };
}

const params = computed(() => {
  defaultDate.value = calculateDefaultDate();
  const urlParams = {
    start_date: route.query.start_date ? route.query.start_date.toString() : defaultDate.value.startDate,
    end_date: route.query.end_date ? route.query.end_date.toString() : defaultDate.value.endDate,
    project_ids: processArrayQueryParameterFromUrl(route.query.project_ids),
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
  };

  return Object.fromEntries(
    Object.entries(urlParams).filter(([_, value]) => value !== undefined)
  ) as GetCanvasserDashboardData['query'];
});

const { data, isLoading, error } = useQuery({
  key: () => ['canvasser.id.dashboard', userId.value, params.value],
  query: () =>
    getCanvasserDashboard({
      composable: '$fetch',
      path: { user_id: userId.value },
      query: params,
    }),
  enabled: () => !!userId.value && route.name === 'users-id-dashboard',
});
</script>

<style scoped lang="scss"></style>
